create index if not exists qm_email_recipient_deliveries_kind_sent_idx
  on public.qm_email_recipient_deliveries (delivery_kind, sent_at desc);

alter table public.qm_email_recipient_deliveries enable row level security;

revoke all on public.qm_email_recipient_deliveries from anon, authenticated;
grant select, insert, update on public.qm_email_recipient_deliveries to service_role;


create table if not exists public.qm_app_ratings (
  id bigint generated by default as identity primary key,
  visitor_hash text not null unique,
  rating smallint not null,
  feedback text,
  feedback_prompt text,
  page_path text,
  visit_count integer not null default 0,
  content_view_count integer not null default 0,
  first_submitted_at timestamptz not null default timezone('utc', now()),
  updated_at timestamptz not null default timezone('utc', now()),
  constraint qm_app_ratings_rating_check check (rating between 1 and 5),
  constraint qm_app_ratings_feedback_length_check check (feedback is null or char_length(feedback) <= 600),
  constraint qm_app_ratings_feedback_prompt_check check (
    feedback_prompt is null or feedback_prompt in ('improvement', 'highlight')
  ),
  constraint qm_app_ratings_page_path_length_check check (page_path is null or char_length(page_path) <= 240),
  constraint qm_app_ratings_visit_count_check check (visit_count between 0 and 100000),
  constraint qm_app_ratings_content_view_count_check check (content_view_count between 0 and 100000)
);

create index if not exists qm_app_ratings_updated_at_idx
  on public.qm_app_ratings (updated_at desc);

create index if not exists qm_app_ratings_rating_updated_at_idx
  on public.qm_app_ratings (rating, updated_at desc);

alter table public.qm_app_ratings enable row level security;

revoke all on public.qm_app_ratings from anon, authenticated;
grant select, insert, update, delete on public.qm_app_ratings to service_role;
grant usage, select on sequence public.qm_app_ratings_id_seq to service_role;


create table if not exists public.qm_analytics_events (
  id bigint generated by default as identity primary key,
  user_id uuid references auth.users(id) on delete set null,
  event_name text not null check (char_length(event_name) between 1 and 80),
  page_path text check (page_path is null or char_length(page_path) <= 240),
  properties jsonb not null default '{}'::jsonb check (jsonb_typeof(properties) = 'object'),
  consent_version text not null,
  created_at timestamptz not null default timezone('utc', now())
);
create index if not exists qm_analytics_events_created_idx on public.qm_analytics_events (created_at desc);
create index if not exists qm_analytics_events_name_created_idx on public.qm_analytics_events (event_name, created_at desc);
alter table public.qm_analytics_events enable row level security;
revoke all on public.qm_analytics_events from anon, authenticated;
grant select, insert on public.qm_analytics_events to service_role;

-- Existing RLS event trigger runs as the database owner; it must not be callable through the public RPC surface.
-- Optional managed helper: absent on some fresh Supabase instances.
do $qm_optional_helper$ begin
  if to_regprocedure('public.rls_auto_enable()') is not null then
    execute 'revoke execute on function public.rls_auto_enable() from public';
  end if;
end $qm_optional_helper$;

-- SOURCE: supabase/migrations/20260914223802_qm_analytics_retention.sql
-- C16: keep consented, non-identifying learning telemetry for no longer than 90 days.

-- Identity is deliberately not part of this dataset.
alter table public.qm_analytics_events
  drop column if exists user_id;

alter table public.qm_analytics_events
  drop constraint if exists qm_analytics_events_allowed_event_name_check;

alter table public.qm_analytics_events
  add constraint qm_analytics_events_allowed_event_name_check
  check (event_name in (
    'session_start',
    'home_study_cta_click',
    'chapter_start',
    'section_open',
    'section_complete',
    'simulator_open',
    'assessment_start',
    'assessment_complete',
    'exercise_generate',
    'exercise_solution_open',
    'exercise_validation_submit',
    'favorite_changed',
    'auth_open',
    'login_success',
    'rating_prompt_shown',
    'rating_submitted',
    'book_preview_open',
    'search_submit',
    'search_result_open'
  ));

comment on table public.qm_analytics_events is
  'Consent-based, non-PII product events. Rows are automatically removed after 90 days.';

create or replace function public.purge_qm_analytics_events()
returns bigint
language plpgsql
security definer
set search_path = ''
as $$
declare
  deleted_count bigint;
begin
  delete from public.qm_analytics_events
  where created_at < timezone('utc', now()) - interval '90 days';

  get diagnostics deleted_count = row_count;
  return deleted_count;
end;
$$;

revoke all on function public.purge_qm_analytics_events() from public, anon, authenticated;
grant execute on function public.purge_qm_analytics_events() to service_role;

create or replace function public.enforce_qm_analytics_retention()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform public.purge_qm_analytics_events();
  return null;
end;
$$;

revoke all on function public.enforce_qm_analytics_retention() from public, anon, authenticated;
grant execute on function public.enforce_qm_analytics_retention() to service_role;

drop trigger if exists qm_analytics_events_enforce_retention on public.qm_analytics_events;
create trigger qm_analytics_events_enforce_retention
before insert on public.qm_analytics_events
for each statement execute function public.enforce_qm_analytics_retention();

-- SOURCE: supabase/migrations/20260924125315_repair_qm_authenticated_learning_flows.sql
-- C21: repair the atomic section-completion reward workflow.
-- Data API privileges are intentionally centralized in the later C27 migration
-- so functional repair and access control remain independently reviewable.

create or replace function public.record_qm_section_completion_reward(
  p_user_id uuid,
  p_idempotency_key text,
  p_chapter_id text,
  p_item_id text,
  p_page_path text
)
returns table (
  awarded boolean,
  xp_delta integer,
  xp_total integer,
  level integer,
  current_streak integer,
  best_streak integer,
  studied_items_count integer
)
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_awarded boolean := false;
  v_today date := (current_timestamp at time zone 'America/Sao_Paulo')::date;
  v_previous_xp integer;
  v_previous_streak integer;
  v_previous_best integer;
  v_previous_active date;
  v_previous_count integer;
  v_next_streak integer;
begin
  if p_user_id is null then
    raise exception using errcode = '22023', message = 'A verified learner is required.';
  end if;

  if p_chapter_id is null or p_chapter_id not in ('01', '02', '03', '04', '05', '06', '07') then
    raise exception using errcode = '22023', message = 'The chapter is not eligible for rewards.';
  end if;

  if nullif(btrim(p_item_id), '') is null
    or nullif(btrim(p_page_path), '') is null
    or nullif(btrim(p_idempotency_key), '') is null
    or length(p_idempotency_key) > 500 then
    raise exception using errcode = '22023', message = 'The reward event is incomplete.';
  end if;

  insert into public.qm_gamification_profiles (user_id)
  values (p_user_id)
  on conflict (user_id) do nothing;

  select
    profile.xp_total,
    profile.current_streak,
    profile.best_streak,
    profile.last_active_on,
    profile.studied_items_count
  into
    v_previous_xp,
    v_previous_streak,
    v_previous_best,
    v_previous_active,
    v_previous_count
  from public.qm_gamification_profiles as profile
  where profile.user_id = p_user_id
  for update;

  insert into public.qm_gamification_events (
    user_id,
    event_type,
    idempotency_key,
    chapter_id,
    item_id,
    page_path,
    xp_delta
  ) values (
    p_user_id,
    'section_completed',
    p_idempotency_key,
    p_chapter_id,
    p_item_id,
    p_page_path,
    20
  )
  on conflict do nothing
  returning true into v_awarded;

  v_awarded := coalesce(v_awarded, false);

  if v_awarded then
    v_next_streak := case
      when v_previous_active = v_today then v_previous_streak
      when v_previous_active = v_today - 1 then v_previous_streak + 1
      else 1
    end;

    update public.qm_gamification_profiles as profile
    set
      xp_total = v_previous_xp + 20,
      level = floor((v_previous_xp + 20) / 100.0)::integer + 1,
      current_streak = v_next_streak,
      best_streak = greatest(v_previous_best, v_next_streak),
      last_active_on = v_today,
      studied_items_count = v_previous_count + 1
    where profile.user_id = p_user_id;
  end if;

  return query
  select
    v_awarded,
    case when v_awarded then 20 else 0 end,
    profile.xp_total,
    profile.level,
    profile.current_streak,
    profile.best_streak,
    profile.studied_items_count
  from public.qm_gamification_profiles as profile
  where profile.user_id = p_user_id;
end;
$$;

revoke all on function public.record_qm_section_completion_reward(uuid, text, text, text, text)
  from public, anon, authenticated;
grant execute on function public.record_qm_section_completion_reward(uuid, text, text, text, text)
  to service_role;

comment on function public.record_qm_section_completion_reward(uuid, text, text, text, text)
  is 'Atomically records one reviewed QM section completion and updates its learner reward projection.';

notify pgrst, 'reload schema';

-- SOURCE: supabase/migrations/20260925215027_explicit_data_api_privileges.sql
-- C27: explicit Data API privileges for the Supabase default change scheduled
-- for 2026-10-30. RLS remains enabled and authoritative for row ownership.
-- This migration makes object reachability explicit and removes implicit grants
-- inherited by older projects before granting only the operations in the
-- versioned access contract.

-- Learner-owned browser data.
revoke all privileges on table public.qm_saved_exercises from anon, authenticated, service_role;
grant select, insert, update, delete on table public.qm_saved_exercises to authenticated;

revoke all privileges on table public.qm_exercise_validation_reports from anon, authenticated, service_role;
grant select on table public.qm_exercise_validation_reports to anon;
grant select, insert, update on table public.qm_exercise_validation_reports to authenticated;
-- Used only by the authorized disposable-audit cleanup path.
grant delete on table public.qm_exercise_validation_reports to service_role;

revoke all privileges on table public.qm_study_progress from anon, authenticated, service_role;
grant select, insert, update, delete on table public.qm_study_progress to authenticated;
grant select on table public.qm_study_progress to service_role;

revoke all privileges on table public.qm_simulator_activity from anon, authenticated, service_role;
grant select, insert, update on table public.qm_simulator_activity to authenticated;

-- Server-only source, assessment, reward, preference, communication, feedback,
-- and analytics data.
revoke all privileges on table public.qm_book_sources from anon, authenticated, service_role;
grant select, insert, update on table public.qm_book_sources to service_role;

revoke all privileges on table public.qm_gamification_profiles from anon, authenticated, service_role;
grant select on table public.qm_gamification_profiles to authenticated;
grant select, insert, update on table public.qm_gamification_profiles to service_role;

revoke all privileges on table public.qm_gamification_events from anon, authenticated, service_role;
grant select on table public.qm_gamification_events to authenticated;
grant select, insert on table public.qm_gamification_events to service_role;

revoke all privileges on table public.qm_chapter_quiz_attempts from anon, authenticated, service_role;
grant select, insert on table public.qm_chapter_quiz_attempts to service_role;

revoke all privileges on table public.qm_user_legal_preferences from anon, authenticated, service_role;
grant select, insert, update on table public.qm_user_legal_preferences to service_role;

revoke all privileges on table public.qm_email_campaigns from anon, authenticated, service_role;
grant select, insert, update on table public.qm_email_campaigns to service_role;

revoke all privileges on table public.qm_email_recipient_deliveries from anon, authenticated, service_role;
grant select, insert, update on table public.qm_email_recipient_deliveries to service_role;

revoke all privileges on table public.qm_app_ratings from anon, authenticated, service_role;
grant select, insert, update, delete on table public.qm_app_ratings to service_role;

revoke all privileges on table public.qm_analytics_events from anon, authenticated, service_role;
grant select, insert on table public.qm_analytics_events to service_role;

-- Identity sequences are separate privilege-bearing objects.
revoke all privileges on sequence public.qm_app_ratings_id_seq from anon, authenticated, service_role;
grant usage, select on sequence public.qm_app_ratings_id_seq to service_role;

revoke all privileges on sequence public.qm_analytics_events_id_seq from anon, authenticated, service_role;
grant usage, select on sequence public.qm_analytics_events_id_seq to service_role;

-- Trigger helpers are not public RPCs. PostgreSQL checks trigger-function
-- execution when a trigger is created, so revoking API-role EXECUTE does not
-- prevent the existing triggers from firing.
revoke all on function public.set_qm_saved_exercises_updated_at() from public, anon, authenticated, service_role;
revoke all on function public.set_qm_exercise_validation_reports_updated_at() from public, anon, authenticated, service_role;
revoke all on function public.set_qm_study_progress_updated_at() from public, anon, authenticated, service_role;
revoke all on function public.set_qm_gamification_updated_at() from public, anon, authenticated, service_role;
revoke all on function public.set_qm_user_legal_preferences_updated_at() from public, anon, authenticated, service_role;

-- Private validator helper: authenticated policies and server-side checks only.
revoke all on function private.is_qm_exercise_validator() from public, anon, authenticated, service_role;
grant execute on function private.is_qm_exercise_validator() to authenticated, service_role;

-- Server-only public RPC surface.
revoke all on function public.purge_qm_analytics_events() from public, anon, authenticated, service_role;
grant execute on function public.purge_qm_analytics_events() to service_role;

revoke all on function public.enforce_qm_analytics_retention() from public, anon, authenticated, service_role;
grant execute on function public.enforce_qm_analytics_retention() to service_role;

revoke all on function public.record_qm_section_completion_reward(uuid, text, text, text, text)
  from public, anon, authenticated, service_role;
grant execute on function public.record_qm_section_completion_reward(uuid, text, text, text, text)
  to service_role;

notify pgrst, 'reload schema';

